export const SNAPSHOT_CAPTURED_AT = '2026-09-23T19:37:00Z';

function weekShiftDays(): number {
  const capturedWeek = getPeriodWeekBounds(new Date(SNAPSHOT_CAPTURED_AT)).start;
  const currentWeek = getPeriodWeekBounds(new Date()).start;
  return Math.round((currentWeek.getTime() - capturedWeek.getTime()) / 86_400_000);
}
const SHIFT_DAYS = weekShiftDays();

function shift(iso: string): Date {
  const d = new Date(iso);
  d.setDate(d.getDate() + SHIFT_DAYS);
  return d;
}

export const offlineOfferings: Offering[] = ROWS.map((row) => {
  const when = shift(row.startTimeISO);
  return { ...row, startTimeISO: when.toISOString(), startTime: formatLockET(when) };
});

/**
 * Seeded results for days already played.
 *
 * Tapping back to a previous day should show how those picks landed, but a
 * first-time viewer has an empty history — so without a seed the
 * correct/incorrect states are unreachable.
 *
 * Each seed's win/loss was DERIVED from the game's real `correctSide` at
 * generation time, not asserted. A hand-written "won" can end up sitting on
 * a card whose other option actually won, and that contradiction is exactly
 * the kind of thing that survives review and then gets spotted in a demo.
 */
