export const offlineDemoHistory: PickRecord[] = SEED.map((s, i) => ({
  id: `seed-${i}`,
  offeringId: s.offeringId,
  question: s.question,
  sport: s.sport as PickRecord['sport'],
  league: s.league,
  chosenOption: s.chosenOption,
  side: s.side as PickRecord['side'],
  status: s.status as PickRecord['status'],
  timestamp: shift(s.startTimeISO).getTime(),
})).sort((a, b) => b.timestamp - a.timestamp);

/** Derived from the same list the cards render, so the two cannot disagree. */
export const offlineDemoStats = {
  weeklyWins: offlineDemoHistory.filter((p) => p.status === 'won').length,
  allTimeWins: offlineDemoHistory.filter((p) => p.status === 'won').length,
  weeklyStreak: (() => {
    let n = 0;
    for (const p of offlineDemoHistory) { if (p.status === 'won') n++; else break; }
    return n;
  })(),
};
